import json

# Save transform function
def copy_patterns(input_grid, output_grid=None):
    """
    Copy colored patterns from input to output, translating:
    - Top patterns: row -1, col -5 (for right section) or row -1, col 0 (for center)
    - Bottom patterns: row -8, col 0 (for left section)
    """
    if output_grid is None:
        out_h, out_w = len(input_grid), len(input_grid[0])
        output_grid = [[0] * out_w for _ in range(out_h)]

    # Find measurement row (row of a complete line of a single color)
    measurement_row = -1
    for r in range(len(input_grid)):
        row = input_grid[r]
        colors = set(c for c in row if c != 0)
        if len(colors) == 1 and sum(c == colors.pop() for c in row) == len(row):
            measurement_row = r
            break

    if measurement_row == -1:
        measurement_row = len(input_grid) // 2  # fallback

    half_h1, half_h2 = measurement_row, len(input_grid) - measurement_row

    for r in range(len(input_grid)):
        row = input_grid[r]
        for c, val in enumerate(row):
            if val != 0:
                out_r = -1
                out_c = -1

                if r < measurement_row:  # Top pattern
                    # Determine if in right section (cols >= measurement_row - 2) or center
                    if c >= measurement_row:
                        out_r = r + 2
                        out_c = c + (-measurement_row)
                    else:
                        out_r = r + 2
                        out_c = c + (1 - measurement_row)
                else:  # Bottom pattern  
                    out_r = r - half_h2 + half_h1
                    out_c = c
                output_grid[out_r][out_c] = val

    return output_grid

