        if name in ['demo1_input', 'demo2_input', 'demo3_input']:
            inp = pair
            exp = pairs[f"{name.replace('input', 'output')}"]
            result = transform_func(inp)
            match = result == exp
            print(f"{name}: {'✓' if match else '✗'}")
            if not match:
                print(f"  Expected:\n{json.dumps(exp)}\n  Got:\n{json.dumps(result)}")
    return all(verify_topology(pairs))

def verify_topology(pairs):
    # Check output grid sizes
    for name, grid in pairs.items():
        name = name.replace('_', '')
        if name.endswith('_input') or name.endswith('_output'):
            inp = name.replace('_output', '')
            if name == '_output':
                pred = pairs[inp]
                if len(grid) != len(pred):
                    print(f"Output {name} has different height than input {inp}")
            if name == '_input':
                if len(grid) != 9:
                    print(f"Unexpected height {len(grid)} for {name}")
    return True

