    """
    inp = grid
    out_h, out_w, inp_h, inp_w = len(grid), len(grid[0]), len(inp), len(inp[0])
    output = [[0] * out_w for _ in range(out_h)]

    # Skip empty input check
    if inp_h == 0 or inp_w == 0:
        return output

    measurement_row = -1
    for r in range(inp_h):
        row = inp[r]
        colors = set(c for c in row if c != 0)
        if len(colors) == 1:
            single_color = list(colors)[0]
            if all(x == single_color or x == 0 for x in row):
                measurement_row = r
                break

    if measurement_row == -1:
        measurement_row = inp_h // 2

    for r in range(inp_h):
        for c in range(inp_w):
            val = inp[r][c]
            if val != 0:
                out_r = r - 1
                out_c = c
                if r >= measurement_row and c >= measurement_row:
                    out_r = r
                    out_c = c - measurement_row + 5
                output[out_r][out_c] = val

    return output

